import java.util.Scanner;
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();

        long[] s = new long[n + 1];
        long[] t = new long[n + 1];

        for (int i = 0; i <= n; i++) {
            s[i] = 1;
            t[i] = 1;
        }

        for (int m = 1; m <= n; m++) {
            long total = 0;
            for (int k = 0; k < m; k++) {
                total += s[m - 1 - k] * s[k];
            }
            s[m] = total;
        }

        for (int _ = 0; _ < h; _++) {
            long[] new_t = new long[n + 1];
            for (int m = 0; m <= n; m++) {
                long total = 0;
                for (int k = 0; k < m; k++) {
                    total += (s[k] - t[k]) * t[m - 1 - k] + s[m - 1 - k] * t[k];
                }
                new_t[m] = total;
            }
            t = new_t;
        }

        System.out.println(t[n]);
        scanner.close();
    }
}
